    id: 'glass-ping', name: 'Glass Ping', ref: 'A struck-glass ping, high and clean', artist: 'Sound design',
    tags: ['perc', 'texture', 'bright'], level: 3,
    blurb: 'A short, clean, high ping with no body to it — a fingernail on the rim of a glass.',
